* macro marker - write some info to callers stack* 11-oct-90 wtg*  ! a5 is used as marker ptr !* !outbuff+$94 must be initialized to outbuff+$9c !* included if "dbg" definedinimark	macro	ifdef	dbg	lea	outbuff+$97(a6),a5	move.l	a5,d0	andi.l	#$FFFFFFFC,d0	movea.l	d0,a5			on long	move.l	#-1,(a5)	endc	endm* marker puts arguments to next location on buffer* use*	marker	number,arg1,arg2...arg7*	number may be anything*	args may be anything what can be inserted in "move.l xxx,(a5)+"*	condition codes not affected marker	macro	ifdef	dbg	ifdef	SUPERVIS	move	sr,(\#+1)*4(a5)	 - after saves	else* next gives warning - but generated code is correct	move	ccr,(\#+1)*4(a5)	 - after saves	endc	move.l	#$F0000000+\1,(a5)+	set marker number	ifge	\#-2	move.l	\2,(a5)+	endc	ifge	\#-3	move.l	\3,(a5)+	endc	ifge	\#-4	move.l	\4,(a5)+	endc	ifge	\#-5	move.l	\5,(a5)+	endc	ifge	\#-6	move.l	\6,(a5)+	endc	ifge	\#-7	move.l	\7,(a5)+	endc	ifge	\#-8	FAIL	marker too many args - max mark+7	endc	move.l	#-1,(a5)		set end	ifdef	SUPERVIS	move.w	4(a5),sr	else	move.w	4(a5),ccr	endc	endc			ifdef dbg	endm